'use strict';
(function(){
  const rowHtml=(item={})=>`<div class="call-point-row" data-call-point-row data-id="${escapeHtml(item.id||'')}"><label>ชื่อจุดเรียกคิว<input data-point-name maxlength="80" value="${escapeHtml(item.name||'')}" placeholder="เช่น ห้องบัตร" required></label><label>คำอ่านออกเสียง<input data-point-spoken maxlength="100" value="${escapeHtml(item.spoken_name||'')}" placeholder="เว้นว่างเพื่อใช้ชื่อจุด"></label><label class="call-point-active"><input data-point-active type="checkbox" ${item.active!==false?'checked':''}> เปิดให้ K-QCall เลือกใช้</label><button type="button" class="secondary" data-point-remove>ลบ</button></div>`;
  async function render(panel){panel.innerHTML='<div class="system-settings-loading">กำลังโหลดจุดเรียกคิว…</div>';try{const result=await kqApi('queue-call-points-settings'),points=result.data||[];panel.innerHTML=`<div class="settings-group-head"><div><span class="eyebrow">K-QCALL DESTINATIONS</span><h3>จุดเรียกคิว</h3><p>กำหนดชื่อที่แสดงและคำอ่านส่วนกลางสำหรับ K-QCall ทุกเครื่อง</p></div><button type="button" class="secondary" data-point-add>＋ เพิ่มจุดเรียกคิว</button></div><div class="call-point-list" data-point-list>${points.map(rowHtml).join('')||'<div class="monitor-empty" data-point-empty>ยังไม่มีจุดเรียกคิว กรุณาเพิ่มอย่างน้อย 1 จุด</div>'}</div><div class="auth-error hidden" data-error></div><div class="settings-actions"><button type="button" class="primary" data-point-save>บันทึกจุดเรียกคิว</button></div>`;const list=panel.querySelector('[data-point-list]'),bindRemove=()=>panel.querySelectorAll('[data-point-remove]').forEach(button=>button.onclick=()=>button.closest('[data-call-point-row]').remove());panel.querySelector('[data-point-add]').onclick=()=>{panel.querySelector('[data-point-empty]')?.remove();list.insertAdjacentHTML('beforeend',rowHtml());bindRemove();list.querySelector('[data-call-point-row]:last-child [data-point-name]')?.focus()};bindRemove();panel.querySelector('[data-point-save]').onclick=async event=>{const button=event.currentTarget,error=panel.querySelector('[data-error]'),items=[...panel.querySelectorAll('[data-call-point-row]')].map((row,index)=>({id:row.dataset.id,name:row.querySelector('[data-point-name]').value.trim(),spoken_name:row.querySelector('[data-point-spoken]').value.trim(),active:row.querySelector('[data-point-active]').checked,sort_order:index})).filter(item=>item.name);button.disabled=true;error.classList.add('hidden');try{await kqApi('queue-call-points-settings',{method:'POST',body:JSON.stringify({points:items})});showToast('บันทึกจุดเรียกคิวสำหรับ K-QCall แล้ว');await render(panel)}catch(err){error.textContent=err.message;error.classList.remove('hidden')}finally{button.disabled=false}}}catch(error){panel.innerHTML=`<div class="auth-error">${escapeHtml(error.message)}</div>`}}
  window.KQCallPointsAdmin={render};
})();
